-- DIRA LEARN - installation in the Supabase SQL Editor, STEP 3 of 5: platform objects and data part 1 of 2
-- Generated by tools/baseline/build_install.py from supabase/baseline - do not edit by hand.
-- Paste the WHOLE file into a new SQL Editor query and press Run. It is one transaction: if anything fails,
-- nothing of this step is kept, and you can simply run it again after the cause is fixed.
-- Sign-up trigger, 6 private storage buckets and their policies, realtime, API account check; then the
-- reference and curriculum data except the teaching notes. Refuses unless STEPS 1-2 are installed.

do $steps$
declare v text;
begin
  if pg_catalog.to_regclass('supabase_migrations.dira_install_steps') is not null then
    execute 'select string_agg(step::text, '','' order by step) from supabase_migrations.dira_install_steps' into v;
  end if;
  if coalesce(v, 'none') <> '1,2' then
    raise exception 'STOP: this is STEP-3. It needs exactly the steps before it installed (1,2); this project has: %. Run STEP-0 to see what to do next. Nothing was changed.', coalesce(v, 'none');
  end if;
end $steps$;
do $guard$
declare v text;
begin
  if pg_catalog.to_regclass('supabase_migrations.schema_migrations') is not null then
    execute 'select string_agg(version, '','' order by version) from supabase_migrations.schema_migrations' into v;
  end if;
  if v is distinct from '20261121000001' then
    raise exception 'STOP: expected the baseline files before this one to be installed (history %), found %. Nothing was changed.', '20261121000001', coalesce(v, 'none');
  end if;
end $guard$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
insert into public.profiles(id, role, status) select u.id, 'applicant', 'active' from auth.users u
 where not exists (select 1 from public.profiles p where p.id = u.id) on conflict (id) do nothing;
