alter table public.tracks disable trigger user; insert into public.tracks(id, programme_id, code, name, focus, "position") select id, programme_id, code, name, focus, "position" from jsonb_populate_recordset(null::public.tracks, $dira_json$[{"id":"0304aafe-1338-465c-a0fc-b756a476a310","programme_id":"00000000-0000-0000-0000-0000000000a1","code":"digital","name":"Digital Marketing","focus":"Reach and win customers online. Learners build a business's online presence, understand their audience, plan and design content, write persuasive copy, use WhatsApp Business, search and simple advertising, measure results, and finish by building and presenting a basic digital marketing campaign for a real Kenyan business, cause or their own idea.","position":1}, {"id":"2653cd8b-059a-4e92-a230-f8c874b397b7","programme_id":"00000000-0000-0000-0000-0000000000a1","code":"ai","name":"AI Tools","focus":"Work smarter with AI, responsibly. Learners understand how AI tools work, write strong prompts, use AI for research, writing, images, presentations, productivity and business tasks, learn simple automation, check AI outputs for accuracy, privacy and bias, and finish by building and demonstrating an AI-assisted solution for a real need.","position":2}, {"id":"5b634bd2-5008-4a74-b026-dc19413903a4","programme_id":"00000000-0000-0000-0000-0000000000a1","code":"entrepreneurship","name":"Entrepreneurship & Business","focus":"Turn an idea into a tested business concept. Learners spot opportunities, understand customer problems and markets, design a value proposition and business model, learn practical money skills (costing, pricing, revenue, expenses and cash flow), market and sell ethically with good customer service, test their idea with real customers, and pitch a business concept.","position":4}, {"id":"f7dd75da-6a76-4cc0-b544-063a8565f290","programme_id":"00000000-0000-0000-0000-0000000000a1","code":"content","name":"Content Creation","focus":"Tell stories people stop for. Learners plan content with a strategy, tell stories, shoot photos and video on a phone with good light, composition and sound, edit video and audio, write captions, design graphics with a consistent brand, use content responsibly and legally, and finish with a content portfolio and a creative project for a real brief.","position":3}]$dira_json$::jsonb); alter table public.tracks enable trigger user;
